export type ParsedSettleInstruction<
  TProgram extends string = typeof CONFIDENTIAL_BATCHER_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    /** Pays the batch authority funding. Anyone. */
    payer: TAccountMetas[0];
    /** Batcher config (carries the direction). */
    batcher: TAccountMetas[1];
    /** The dispatched batch being settled. */
    batch: TAccountMetas[2];
    /**
     * depositor/withdrawer, and wrap owner via invoke_signed. Receives
     * funding for the rent the wrap execution (and any other owner-charged CPIs)
     * charge to the owner; redemption closes the already-open pending burn.
     */
    batchAuthority: TAccountMetas[3];
    /** Confidential mint the batch total was burned on. */
    joinConfidentialMint: TAccountMetas[4];
    batchJoinTokenAccount: TAccountMetas[5];
    /**
     * SPL mint the join confidential mint wraps (vault underlying for deposit
     * batchers, vault shares for redeem batchers). Mutable because it is the
     * vault share mint on the redeem direction (phase 2 burns from it).
     */
    joinUnderlyingMint: TAccountMetas[6];
    /** by the token CPI. */
    joinMintVaultUnderlying: TAccountMetas[7];
    joinMintVaultAuthority: TAccountMetas[8];
    /** Batch's plain SPL account receiving the redeemed batch total. */
    batchJoinUnderlying: TAccountMetas[9];
    batchBurnedAmountStore: TAccountMetas[10];
    pendingBurn: TAccountMetas[11];
    hostConfig: TAccountMetas[12];
    /** verifier CPI. */
    kmsContext: TAccountMetas[13];
    /** Public vault the batcher fronts. */
    vault: TAccountMetas[14];
    vaultAuthority: TAccountMetas[15];
    vaultTokenAccount: TAccountMetas[16];
    /** Batch's plain SPL account receiving the vault phase's output. */
    batchPayoutUnderlying: TAccountMetas[17];
    /** Confidential mint claims pay out in. */
    payoutConfidentialMint: TAccountMetas[18];
    /**
     * SPL mint the payout confidential mint wraps (vault shares for deposit
     * batchers, vault underlying for redeem batchers). Mutable because it is
     * the vault share mint on the deposit direction (phase 2 mints to it).
     */
    payoutUnderlyingMint: TAccountMetas[19];
    batchPayoutTokenAccount: TAccountMetas[20];
    /** by the token CPI. */
    payoutMintVaultUnderlying: TAccountMetas[21];
    payoutMintVaultAuthority: TAccountMetas[22];
    payoutTotalSupplyAuthority: TAccountMetas[23];
    batchPayoutBalanceStore: TAccountMetas[24];
    payoutTotalSupplyStore: TAccountMetas[25];
    zamaEventAuthority: TAccountMetas[26];
    transientStore: TAccountMetas[27];
    instructions: TAccountMetas[28];
    /** ZamaHost program (FHE compute + ACL). */
    zamaProgram: TAccountMetas[29];
    confidentialTokenEventAuthority: TAccountMetas[30];
    /** confidential-token program composed via CPI. */
    confidentialTokenProgram: TAccountMetas[31];
    /** demo-vault program composed via CPI. */
    demoVaultProgram: TAccountMetas[32];
    /** SPL token program. */
    tokenProgram: TAccountMetas[33];
    /** System program used for account creation. */
    systemProgram: TAccountMetas[34];
  };
  data: SettleInstructionData;
};

export function parseSettleInstruction<TProgram extends string, TAccountMetas extends readonly AccountMeta[]>(
  instruction: Instruction<TProgram> & InstructionWithAccounts<TAccountMetas> & InstructionWithData<ReadonlyUint8Array>,
): ParsedSettleInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 35) {
    throw new SolanaError(SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS, {
      actualAccountMetas: instruction.accounts.length,
      expectedAccountMetas: 35,
    });
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      payer: getNextAccount(),
      batcher: getNextAccount(),
      batch: getNextAccount(),
      batchAuthority: getNextAccount(),
      joinConfidentialMint: getNextAccount(),
      batchJoinTokenAccount: getNextAccount(),
      joinUnderlyingMint: getNextAccount(),
      joinMintVaultUnderlying: getNextAccount(),
      joinMintVaultAuthority: getNextAccount(),
      batchJoinUnderlying: getNextAccount(),
      batchBurnedAmountStore: getNextAccount(),
      pendingBurn: getNextAccount(),
      hostConfig: getNextAccount(),
      kmsContext: getNextAccount(),
      vault: getNextAccount(),
      vaultAuthority: getNextAccount(),
      vaultTokenAccount: getNextAccount(),
      batchPayoutUnderlying: getNextAccount(),
      payoutConfidentialMint: getNextAccount(),
      payoutUnderlyingMint: getNextAccount(),
      batchPayoutTokenAccount: getNextAccount(),
      payoutMintVaultUnderlying: getNextAccount(),
      payoutMintVaultAuthority: getNextAccount(),
      payoutTotalSupplyAuthority: getNextAccount(),
      batchPayoutBalanceStore: getNextAccount(),
      payoutTotalSupplyStore: getNextAccount(),
      zamaEventAuthority: getNextAccount(),
      transientStore: getNextAccount(),
      instructions: getNextAccount(),
      zamaProgram: getNextAccount(),
      confidentialTokenEventAuthority: getNextAccount(),
      confidentialTokenProgram: getNextAccount(),
      demoVaultProgram: getNextAccount(),
      tokenProgram: getNextAccount(),
      systemProgram: getNextAccount(),
    },
    data: getSettleInstructionDataDecoder().decode(instruction.data),
  };
}
